// This code has been fully generated by an AI.
//
// Pure theme helpers. No DOM access, so the module can be tested with
// node --test (see jstest/theme-data.test.mjs).

export const THEME_KEY = "myvelo.theme";
export const THEMES = ["light", "dark", "system"];

/** Stored choice or the default "light" for missing/unknown values. */
export function normalizeTheme(value) {
  return THEMES.includes(value) ? value : "light";
}

/**
 * uPlot axis options in the theme colors. uPlot draws on a canvas, which
 * ignores CSS color-scheme, so every color must be passed explicitly.
 * colors: { axis, grid } as CSS color strings.
 */
export function axisStyle(colors, extra = {}) {
  return {
    stroke: colors.axis,
    grid: { stroke: colors.grid, width: 1 },
    ticks: { stroke: colors.grid, width: 1 },
    font: "12px system-ui, sans-serif",
    labelFont: "12px system-ui, sans-serif",
    ...extra,
  };
}

/** Appends a two-digit hex alpha to a #rrggbb color. */
export function withAlpha(hex, alpha) {
  if (!/^#[0-9a-f]{6}$/i.test(hex)) return hex;
  const a = Math.round(Math.min(1, Math.max(0, alpha)) * 255);
  return hex + a.toString(16).padStart(2, "0");
}
